source='''from collections import Counter, defaultdict


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                p = stack.pop()
                cells.add(p)
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (p[0] + dr, p[1] + dc)
                    if (0 <= q[0] < h and 0 <= q[1] < w
                            and q not in seen and grid[q[0]][q[1]] == color):
                        seen.add(q)
                        stack.append(q)
            result.append((color, cells))
    return result


def _bbox(cells):
    rows = [r for r, _ in cells]
    cols = [c for _, c in cells]
    return min(rows), min(cols), max(rows), max(cols)


def _is_corner_line(cells):
    r0, c0, r1, c1 = _bbox(cells)
    if r0 == r1 or c0 == c1:
        return False
    corners = ((r0, c0), (r0, c1), (r1, c0), (r1, c1))
    for r, c in corners:
        expected = ({(r, x) for x in range(c0, c1 + 1)}
                    | {(y, c) for y in range(r0, r1 + 1)})
        if cells == expected:
            return True
    return False


def _shape(cells):
    r0, c0, _, _ = _bbox(cells)
    return frozenset((r - r0, c - c0) for r, c in cells)


def _inside(box, outer):
    return (outer[0] <= box[0] and outer[1] <= box[1]
            and box[2] <= outer[2] and box[3] <= outer[3])


def _disjoint(a, b):
    return a[2] < b[0] or a[0] > b[2] or a[3] < b[1] or a[1] > b[3]


def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    objects = [(color, cells, _bbox(cells))
               for color, cells in _components(grid) if color != background]
    keys = [(color, cells, box) for color, cells, box in objects
            if _is_corner_line(cells)]
    if not keys:
        return out
    key_color, key_cells, key_box = max(keys, key=lambda obj: len(obj[1]))

    groups = defaultdict(list)
    for obj in objects:
        if obj[1] != key_cells:
            groups[_shape(obj[1])].append(obj)
    candidates = []
    for members in groups.values():
        internal = [obj for obj in members if _inside(obj[2], key_box)]
        external = [obj for obj in members if _disjoint(obj[2], key_box)]
        if internal and external:
            candidates.extend(external)
    if len(candidates) == 1:
        for r, c in candidates[0][1]:
            out[r][c] = key_color
    return out
